  package     org . apache . commons . collections4 . bloomfilter ;   public final class BloomFilterIndexer  {   private static final  int  DIVIDE_BY_64 = 6 ;   private BloomFilterIndexer  ( )  { }   public static void checkPositive  (   int bitIndex )  {  if  (  bitIndex < 0 )  {  throw  new IndexOutOfBoundsException  (  "Negative bitIndex: " + bitIndex ) ; } }   public static  int getLongIndex  (   int bitIndex )  {  return  bitIndex >> DIVIDE_BY_64 ; }   public static  long getLongBit  (   int bitIndex )  {  return  1L << bitIndex ; } }